using System;
using Microsoft.Data.Sqlite;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using TCAdmin.SDK.Database.Entities;
var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// CreateHostedService: creates this service's TeamSpeak virtual server inside the master and saves its
// id (Sid) and the Server Admin privilege key. TeamSpeak starts a new server (whatever its autostart
// flag), so it is stopped again: the panel's own start (Start after creation, or the user) starts it.
// virtualserver_autostart is the state TeamSpeak restores when the master restarts; the start script
// turns it on and the stop script off, so a new server leaves here with it off.
// The service folder is linked to the virtual server's files by the AfterServiceCreated script, not here:
// TeamSpeak fills files\virtualserver_<sid> at servercreate, and the panel's template copy (which runs
// between the two) refuses a destination that is not empty.
void Out(string s) => ScriptConsole.WriteLine((s ?? "").Replace("{", "{{").Replace("}", "}}"));

int port = ThisService.GamePort;
int slots = ThisService.Slots > 0 ? ThisService.Slots : 32;
string name = Ts3ServerName();
string password = Ts3Var("Password");
string welcome = Ts3Var("WelcomeMessage").Trim();
if (port <= 0) throw new Exception("The service has no GamePort (voice port) assigned.");

using (var ts = Ts3Connect())
{
    if (ts.ServerList().Any(s => Ts3Query.Int(s, "virtualserver_port") == port))
        throw new Exception($"Port {port} is already used by another virtual server of this TeamSpeak master.");

    var command = new StringBuilder("servercreate");
    command.Append(" virtualserver_name=").Append(Ts3Query.Escape(name));
    command.Append(" virtualserver_port=").Append(port);
    command.Append(" virtualserver_maxclients=").Append(slots);
    command.Append(" virtualserver_autostart=0");
    if (password.Length > 0) command.Append(" virtualserver_password=").Append(Ts3Query.Escape(password));
    if (welcome.Length > 0) command.Append(" virtualserver_welcomemessage=").Append(Ts3Query.Escape(welcome));

    var reply = ts.Execute(command.ToString());
    if (reply.ErrorId == Ts3RunningLimit)
        throw new Exception("The TeamSpeak license does not allow another running virtual server, and TeamSpeak starts a new one when it creates it. Stop another virtual server of this master and try again.");
    if (reply.ErrorId != 0) throw new Ts3Exception(reply.ErrorId, reply.ErrorMessage);
    var created = reply.Rows.FirstOrDefault() ?? new Dictionary<string, string>();
    int sid = Ts3Query.Int(created, "sid");
    string token = Ts3Query.Str(created, "token");
    if (sid <= 0) throw new Exception("TeamSpeak did not return the new virtual server's id.");
    Out($"Created TeamSpeak virtual server #{sid} '{name}' on port {port} with {slots} slots.");

    try
    {
        var stop = ts.Execute($"serverstop sid={sid}");
        if (stop.ErrorId != 0 && stop.ErrorId != Ts3ServerNotRunning) throw new Ts3Exception(stop.ErrorId, stop.ErrorMessage);

        ThisService.Variables["Sid"] = sid.ToString();
        ThisService.Variables["PrivilegeKey"] = token;
    }
    catch
    {
        // Undo our own work; the panel only calls DeleteHostedService after a successful create.
        try { ts.Execute($"serverstop sid={sid}"); ts.Execute($"serverdelete sid={sid}"); } catch { }
        ThisService.Variables.Remove("Sid");
        ThisService.Variables.Remove("PrivilegeKey");
        throw;
    }
}
// ---------------------------------------------------------------------------------------------
// Host connection: this virtual server lives inside the TeamSpeak 3 master (HostService). Every
// script of this blueprint carries the same copy - keep them identical when changing it.
// ---------------------------------------------------------------------------------------------
GameService Ts3Host() => HostService
    ?? throw new Exception("The TeamSpeak 3 master (host service) of this virtual server was not found.");

string Ts3HostAddress()
{
    var ip = Ts3Host().IPAddress;
    if (string.IsNullOrEmpty(ip)) ip = ThisService.IPAddress; // a hosted row always sits on the host's IP
    return string.IsNullOrEmpty(ip) ? "127.0.0.1" : ip;
}

/// <summary>Opens a ServerQuery session on the master, logged in as serveradmin (the master's RCON password).</summary>
Ts3Query Ts3Connect(int timeoutMs = 5000)
{
    var host = Ts3Host();
    var ts = new Ts3Query(Ts3HostAddress(), host.Ports["QueryPort"], timeoutMs);
    try { ts.Login("serveradmin", host.Variables.Parse<string>("RconPassword", string.Empty)); }
    catch { ts.Dispose(); throw; }
    return ts;
}

/// <summary>The TeamSpeak virtual server id saved by CreateHostedService (0 = none).</summary>
int Ts3Sid() => int.TryParse(ThisService.Variables.Parse<string>("Sid", string.Empty), out var sid) ? sid : 0;

/// <summary>A variable value, or the fallback when it is unset or still an unresolved ${...} token.</summary>
string Ts3Var(string name, string fallback = "")
{
    var value = ThisService.Variables.Parse<string>(name, string.Empty) ?? string.Empty;
    return value.Length == 0 || value.Contains("${") ? fallback : value;
}

/// <summary>The virtual server name: the ServerName variable, else the service name.</summary>
string Ts3ServerName() => Ts3Var("ServerName", ThisService.Name ?? "TeamSpeak Server").Trim();

/// <summary>A monthly file-transfer quota in MB for serveredit: 0 (unlimited) is TeamSpeak's "no quota" value.</summary>
string Ts3Quota(int megabytes) => megabytes > 0 ? megabytes.ToString() : "18446744073709551615";

/// <summary>The serveredit arguments that re-apply every panel-managed setting (name, password, messages, quotas).</summary>
string Ts3SettingsArguments() =>
    " virtualserver_name=" + Ts3Query.Escape(Ts3ServerName()) +
    " virtualserver_password=" + Ts3Query.Escape(Ts3Var("Password")) +
    " virtualserver_welcomemessage=" + Ts3Query.Escape(Ts3Var("WelcomeMessage").Trim()) +
    " virtualserver_hostmessage=" + Ts3Query.Escape(Ts3Var("HostMessage").Trim()) +
    " virtualserver_hostmessage_mode=" + (int.TryParse(Ts3Var("HostMessageMode"), out var mode) && mode >= 0 && mode <= 3 ? mode : 0) +
    " virtualserver_upload_quota=" + Ts3Quota(int.TryParse(Ts3Var("UploadQuota"), out var up) ? up : 0) +
    " virtualserver_download_quota=" + Ts3Quota(int.TryParse(Ts3Var("DownloadQuota"), out var down) ? down : 0);

// TeamSpeak error ids used by these scripts.
const int Ts3InvalidServerId = 1024, Ts3ServerRunning = 1025, Ts3ServerNotRunning = 1033, Ts3RunningLimit = 2816;


