// StartHostedService: starts the virtual server, turns its autostart on (TeamSpeak brings it back when
// the master restarts), then re-applies the panel's settings (slots, name, password, welcome message)
// so a change made in the panel takes effect at every start. Started first because TeamSpeak refuses
// to open a stopped server (use -virtual) while the license's running limit is reached.
void Out(string s) => ScriptConsole.WriteLine((s ?? "").Replace("{", "{{").Replace("}", "}}"));

int sid = Ts3Sid();
if (sid <= 0) throw new Exception("This service has no TeamSpeak virtual server id (Sid variable).");

using (var ts = Ts3Connect())
{
    var start = ts.Execute($"serverstart sid={sid}");
    // At the license's running limit TeamSpeak answers 2816 even for a server that is already running.
    if (start.ErrorId == Ts3RunningLimit &&
        ts.ServerList().Any(s => Ts3Query.Int(s, "virtualserver_id") == sid && Ts3Query.Str(s, "virtualserver_status") == "online"))
        start = new Ts3Reply { ErrorId = Ts3ServerRunning };
    if (start.ErrorId == Ts3RunningLimit)
        throw new Exception("The TeamSpeak license does not allow another running virtual server.");
    if (start.ErrorId == Ts3InvalidServerId)
        throw new Exception($"TeamSpeak virtual server #{sid} no longer exists on the master.");
    if (start.ErrorId != 0 && start.ErrorId != Ts3ServerRunning)
        throw new Ts3Exception(start.ErrorId, start.ErrorMessage);
    Out(start.ErrorId == Ts3ServerRunning ? $"Virtual server #{sid} was already running." : $"Started virtual server #{sid}.");

    ts.Send($"use sid={sid}");
    ts.Send("serveredit virtualserver_autostart=1");
    ts.Send("serveredit virtualserver_maxclients=" + (ThisService.Slots > 0 ? ThisService.Slots : 32) + Ts3SettingsArguments());
    Out("Autostart on; applied slots, name, password, messages and quotas.");
}
