    var use = ts.Execute($"use sid={sid} -virtual");
    if (use.ErrorId == Ts3InvalidServerId) { Out($"Virtual server #{sid} no longer exists on the master."); return; }
    if (use.ErrorId != 0) Out($"Warning: could not select virtual server #{sid} to turn autostart off: {use.ErrorMessage}");
    else
    {
        var edit = ts.Execute("serveredit virtualserver_autostart=0");
        if (edit.ErrorId != 0) Out($"Warning: could not turn autostart off for virtual server #{sid}: {edit.ErrorMessage}");
        else Out($"Autostart off for virtual server #{sid}.");
    }

    var stop = ts.Execute($"serverstop sid={sid}");
    if (stop.ErrorId == Ts3ServerNotRunning || stop.ErrorId == Ts3InvalidServerId) Out($"Virtual server #{sid} was not running.");
    else if (stop.ErrorId != 0) throw new Ts3Exception(stop.ErrorId, stop.ErrorMessage);
    else Out($"Stopped virtual server #{sid}.");
}
