var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// CustomQueryProtocol: this virtual server's slots, voice clients and player list, read through the
// master's ServerQuery. Name is the TeamSpeak virtual server name: the panel renames the service from
// the query Name, so the service follows the name set in TeamSpeak or by "Edit server settings".
// Hostname is the voice address - the one a TeamSpeak client connects to.
int sid = Ts3Sid();
string address = Ts3HostAddress();
string hostname = $"{address}:{ThisService.GamePort}";
GameQueryResponse Offline(string reason) => new GameQueryResponse
{
    Status = "offline", Hostname = hostname, Name = ThisService.Name, GameType = "TeamSpeak 3",
    Map = reason, MaxPlayers = ThisService.Slots, Players = new List<GameQueryPlayer>(), Rules = new Dictionary<string, string>(),
};

if (sid <= 0)
{
    Globals.ReturnValue = Offline("No virtual server id");
    return;
}

using (var ts = Ts3Connect(3000))
{
    var use = ts.Execute($"use sid={sid}");
    if (use.ErrorId != 0)
    {
        Globals.ReturnValue = Offline(use.ErrorId == Ts3ServerNotRunning ? "Virtual server stopped" : "TeamSpeak error " + use.ErrorId + ": " + use.ErrorMessage);
        return;
    }
    var info = ts.SendSingle("serverinfo");
    int clients = Math.Max(0, Ts3Query.Int(info, "virtualserver_clientsonline") - Ts3Query.Int(info, "virtualserver_queryclientsonline"));
    long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
    var players = new List<GameQueryPlayer>();
    if (clients > 0)
    {
        foreach (var c in ts.Send("clientlist -times"))
        {
            if (Ts3Query.Int(c, "client_type") != 0) continue; // 1 = ServerQuery client
            long last = Ts3Query.Int(c, "client_lastconnected");
            players.Add(new GameQueryPlayer
            {
                Name = Ts3Query.Str(c, "client_nickname"),
                ConnectTime = last > 0 ? (int)Math.Max(0, now - last) : 0,
            });
        }
    }
    string version = Ts3Query.Str(info, "virtualserver_version").Split(' ')[0];
    Globals.ReturnValue = new GameQueryResponse
    {
        Status = "online",
        Hostname = hostname,
        Name = string.IsNullOrWhiteSpace(Ts3Query.Str(info, "virtualserver_name")) ? ThisService.Name : Ts3Query.Str(info, "virtualserver_name").Trim(),
        GameType = string.IsNullOrEmpty(version) ? "TeamSpeak 3" : "TeamSpeak 3 v" + version,
        Map = Ts3Query.Str(info, "virtualserver_channelsonline", "0") + " channel(s)",
        NumPlayers = clients,
        MaxPlayers = Ts3Query.Int(info, "virtualserver_maxclients"),
        Players = players,
        Rules = new Dictionary<string, string>
        {
            ["sid"] = sid.ToString(),
            ["port"] = Ts3Query.Str(info, "virtualserver_port"),
            ["channels"] = Ts3Query.Str(info, "virtualserver_channelsonline"),
            ["password"] = Ts3Query.Str(info, "virtualserver_flag_password") == "1" ? "yes" : "no",
            ["uptime"] = Ts3Query.Str(info, "virtualserver_uptime"),
        },
    };
}
