                case 'f': sb.Append('\f'); break;
                case 'n': sb.Append('\n'); break;
                case 'r': sb.Append('\r'); break;
                case 't': sb.Append('\t'); break;
                case 'v': sb.Append('\v'); break;
                default: sb.Append('\\').Append(n); break;
            }
        }
        return sb.ToString();
    }
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, Microsoft.Data.Sqlite.dll, Microsoft.EntityFrameworkCore.dll
using System;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using TCAdmin.SDK.Database.Entities;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE


// API function "TsServer": THIS service's virtual server, for the TeamSpeak Browser page.
// TsAction = info | edit | bandwidth | logs.
// info       -> the serverinfo row + the panel-managed settings (the service variables)
// edit       TsName, TsPassword / TsClearPassword, TsWelcomeMessage, TsHostMessage, TsHostMessageMode (0-3),
//            TsUploadQuota, TsDownloadQuota (MB per month, 0 = unlimited). Saved in the service's variables
//            (every start re-applies them) and applied live when the virtual server is running.
//            Slots stay the panel's Slots setting; start/stop are the service's own power buttons.
// bandwidth  -> the connection-info row
// logs       TsLines (max 100) -> { lines, fileSize } the last lines, oldest first
var action = Action();
int sid = Ts3Sid();
if (sid <= 0) throw Fail("This service has no TeamSpeak virtual server id (Sid variable) yet.");
switch (action)
{
    case "info":
    {
        using (var ts = Ts3Connect())
        {
            ts.Use(sid);
            var info = ServerInfoRow(ts, sid);
            info["settings"] = new Dictionary<string, object>
            {
                ["name"] = Ts3ServerName(), ["passwordProtected"] = Ts3Var("Password").Length > 0,
                ["welcomeMessage"] = Ts3Var("WelcomeMessage"), ["hostMessage"] = Ts3Var("HostMessage"),
                ["hostMessageMode"] = int.TryParse(Ts3Var("HostMessageMode"), out var mode) ? mode : 0,
                ["uploadQuotaMb"] = int.TryParse(Ts3Var("UploadQuota"), out var up) ? up : 0,
                ["downloadQuotaMb"] = int.TryParse(Ts3Var("DownloadQuota"), out var down) ? down : 0,
                ["slots"] = ThisService.Slots
            };
            info["serviceId"] = ThisService.ServiceId;
            Globals.ReturnValue = info;
        }
        break;
    }
    case "edit":
    {
        string name = Arg("TsName", Ts3ServerName()).Trim();
        if (name.Length == 0) throw Fail("TsName (the server name) is required.");
        string password = BoolArg("TsClearPassword") ? "" : (Arg("TsPassword").Length > 0 ? Arg("TsPassword") : Ts3Var("Password"));
        string welcome = (GetValue<object>("TsWelcomeMessage") != null ? Arg("TsWelcomeMessage") : Ts3Var("WelcomeMessage")).Trim();
        string hostMessage = (GetValue<object>("TsHostMessage") != null ? Arg("TsHostMessage") : Ts3Var("HostMessage")).Trim();
        int hostMessageMode = Math.Clamp(GetValue<object>("TsHostMessageMode") != null ? IntArg("TsHostMessageMode") : (int.TryParse(Ts3Var("HostMessageMode"), out var m) ? m : 0), 0, 3);
        int uploadQuota = Math.Max(0, GetValue<object>("TsUploadQuota") != null ? IntArg("TsUploadQuota") : (int.TryParse(Ts3Var("UploadQuota"), out var u) ? u : 0));
        int downloadQuota = Math.Max(0, GetValue<object>("TsDownloadQuota") != null ? IntArg("TsDownloadQuota") : (int.TryParse(Ts3Var("DownloadQuota"), out var d) ? d : 0));

        bool live = false;
        using (var ts = Ts3Connect())
        {
            var use = ts.Execute($"use sid={sid}");
            if (use.ErrorId == 0)
            {
                ts.Send("serveredit virtualserver_name=" + Ts3Query.Escape(name) +
                        " virtualserver_password=" + Ts3Query.Escape(password) +
                        " virtualserver_welcomemessage=" + Ts3Query.Escape(welcome) +
                        " virtualserver_hostmessage=" + Ts3Query.Escape(hostMessage) +
                        " virtualserver_hostmessage_mode=" + hostMessageMode +
                        " virtualserver_upload_quota=" + Ts3Quota(uploadQuota) +
                        " virtualserver_download_quota=" + Ts3Quota(downloadQuota));
                live = true;
            }
            else if (use.ErrorId != Ts3ServerNotRunning)
            {
                throw new Ts3Exception(use.ErrorId, use.ErrorMessage);
            }
        }

        // Service.Variables has no EF value comparer, so the entity is marked Modified explicitly.
        var service = await ServiceManager.GetAsync(ThisService.ServiceId)
                      ?? throw Fail($"Service {ThisService.ServiceId} was not found.");
        service.Name = name; // the service follows the virtual server name (the query reports it too)
        service.Variables["ServerName"] = name;
        service.Variables["Password"] = password;
        service.Variables["WelcomeMessage"] = welcome;
        service.Variables["HostMessage"] = hostMessage;
        service.Variables["HostMessageMode"] = hostMessageMode.ToString();
        service.Variables["UploadQuota"] = uploadQuota.ToString();
        service.Variables["DownloadQuota"] = downloadQuota.ToString();
        ServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
        await ServiceManager.SaveChangesAsync(ThisCancellationToken);
        Globals.ReturnValue = new { ok = true, live, name };
        break;
    }
    case "bandwidth":
    {
        using (var ts = Ts3Connect())
        {
            ts.Use(sid);
            var row = BandwidthRow(ts);
            row["sid"] = sid;
            Globals.ReturnValue = row;
        }
        break;
    }
    case "logs":
    {
        using (var ts = Ts3Connect())
        {
            ts.Use(sid);
            Globals.ReturnValue = LogPage(ts, IntArg("TsLines", 100), instance: false);
        }
        break;
    }
    default:
        throw Fail($"Unknown TsAction '{action}'. Use info, edit, bandwidth or logs.");
}


// ---------------------------------------------------------------------------------------------
// API-function helpers. The TeamSpeak Browser page calls these scripts through
// TCAdmin.Script.Execute(name, { TsAction: "...", ... }); every argument is a declared script
// input variable (Ts*). The result is Globals.ReturnValue; a thrown exception is the call's error.
// Every TeamSpeak Browser function of this blueprint carries the same copy - keep them identical.
// ---------------------------------------------------------------------------------------------
string Arg(string name, string fallback = "")
{
    var value = GetValue<object>(name);
    var text = value == null ? "" : Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";
    return text.Length == 0 ? fallback : text;
}
int IntArg(string name, int fallback = 0) =>
    double.TryParse(Arg(name), NumberStyles.Float, CultureInfo.InvariantCulture, out var d) ? (int)Math.Round(d) : fallback;
bool BoolArg(string name) => Arg(name).Equals("true", StringComparison.OrdinalIgnoreCase) || Arg(name) == "1";
string Action() => Arg("TsAction").Trim().ToLowerInvariant();
Exception Fail(string message) => new Exception(message);
string Nz(Dictionary<string, string> row, string key) => Ts3Query.Str(row, key);
int Ni(Dictionary<string, string> row, string key, int fallback = 0) => Ts3Query.Int(row, key, fallback);
long Nl(Dictionary<string, string> row, string key) => long.TryParse(Ts3Query.Str(row, key), out var l) ? l : 0;

/// <summary>Server groups of the selected virtual server: sgid -> name (regular groups only).</summary>
Dictionary<int, string> ServerGroups(Ts3Query ts) =>
    ts.Send("servergrouplist").Where(g => Ni(g, "type") == 1 && g.ContainsKey("sgid"))
      .ToDictionary(g => Ni(g, "sgid"), g => Nz(g, "name"));

/// <summary>Channels of the selected virtual server as browser rows, in TeamSpeak's display order.</summary>
List<Dictionary<string, object>> ChannelRows(Ts3Query ts)
{
    var rows = ts.Send("channellist -topic -flags -voice -limits").Where(c => c.ContainsKey("cid")).ToList();
    var byParent = rows.GroupBy(c => Ni(c, "pid")).ToDictionary(g => g.Key, g => g.ToList());
    var ordered = new List<Dictionary<string, object>>();
    void Walk(int pid, int depth)
    {
        if (!byParent.TryGetValue(pid, out var children)) return;
        // channel_order is the id of the channel ABOVE a channel; 0 = first.
        var remaining = children.ToList();
        int previous = 0;
        while (remaining.Count > 0)
        {
            var next = remaining.FirstOrDefault(c => Ni(c, "channel_order") == previous) ?? remaining[0];
            remaining.Remove(next);
            int cid = Ni(next, "cid");
            ordered.Add(new Dictionary<string, object>
            {
                ["cid"] = cid, ["pid"] = pid, ["depth"] = depth,
                ["name"] = Nz(next, "channel_name"), ["topic"] = Nz(next, "channel_topic"),
                ["clients"] = Ni(next, "total_clients"),
                ["maxClients"] = Ni(next, "channel_flag_maxclients_unlimited") == 1 ? -1 : Ni(next, "channel_maxclients", -1),
                ["permanent"] = Ni(next, "channel_flag_permanent") == 1,
                ["semiPermanent"] = Ni(next, "channel_flag_semi_permanent") == 1,
                ["isDefault"] = Ni(next, "channel_flag_default") == 1,
                ["passworded"] = Ni(next, "channel_flag_password") == 1,
                ["codec"] = Ni(next, "channel_codec"), ["codecQuality"] = Ni(next, "channel_codec_quality"),
                ["neededTalkPower"] = Ni(next, "channel_needed_talk_power"),
                ["neededSubscribePower"] = Ni(next, "channel_needed_subscribe_power")
            });
            previous = cid;
            Walk(cid, depth + 1);
        }
    }
    Walk(0, 0);
    return ordered;
}

