{
    var host = Ts3Host();
    var ts = new Ts3Query(Ts3HostAddress(), host.Ports["QueryPort"], timeoutMs);
    try { ts.Login("serveradmin", host.Variables.Parse<string>("RconPassword", string.Empty)); }
    catch { ts.Dispose(); throw; }
    return ts;
}

