/// <summary>Opens a ServerQuery session on the master, logged in as serveradmin (the master's RCON password).</summary>
Ts3Query Ts3Connect(int timeoutMs = 5000)
{
    var host = Ts3Host();
    var ts = new Ts3Query(Ts3HostAddress(), host.Ports["QueryPort"], timeoutMs);
    try { ts.Login("serveradmin", host.Variables.Parse<string>("RconPassword", string.Empty)); }
    catch { ts.Dispose(); throw; }
    return ts;
}

