var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE


// API function "TsBans": the ban list of a virtual server, for the TeamSpeak Browser page.
// TsAction = list | add | delete | clear.
// list    -> [{ banId, ip, name, uid, lastNickname, created, durationSeconds, reason, invoker, enforcements }]
// add     TsIp and/or TsUid, TsMinutes (0 = permanent), TsReason -> { banId }
// delete  TsBanId
// clear   removes every ban
var action = Action();
using (var ts = Ts3Connect())
{
    int sid = UseSid(ts);
    switch (action)
    {
        case "list":
            Globals.ReturnValue = ts.Send("banlist").Where(b => b.ContainsKey("banid")).OrderBy(b => Ni(b, "banid")).Select(b => new Dictionary<string, object>
            {
                ["banId"] = Ni(b, "banid"), ["ip"] = Nz(b, "ip"), ["name"] = Nz(b, "name"), ["uid"] = Nz(b, "uid"),
                ["lastNickname"] = Nz(b, "lastnickname"), ["created"] = Nl(b, "created"), ["durationSeconds"] = Nl(b, "duration"),
                ["reason"] = Nz(b, "reason"), ["invoker"] = Nz(b, "invokername"), ["enforcements"] = Ni(b, "enforcements")
            }).ToList();
            break;
        case "add":
        {
            var ip = Arg("TsIp").Trim(); var uid = Arg("TsUid").Trim();
            if (ip.Length == 0 && uid.Length == 0) throw Fail("TsIp or TsUid is required.");
            int minutes = Math.Max(0, IntArg("TsMinutes"));
            var cmd = "banadd" + (ip.Length > 0 ? $" ip={Ts3Query.Escape(ip)}" : "") + (uid.Length > 0 ? $" uid={Ts3Query.Escape(uid)}" : "") +
                      (minutes > 0 ? $" time={minutes * 60}" : "") + $" banreason={Ts3Query.Escape(Arg("TsReason", "Banned by an administrator"))}";
            var row = ts.SendSingle(cmd);
            Globals.ReturnValue = new { ok = true, banId = Ni(row, "banid") };
            break;
        }
        case "delete":
        {
            int banId = IntArg("TsBanId"); if (banId <= 0) throw Fail("TsBanId is required.");
            ts.Send($"bandel banid={banId}");
            Globals.ReturnValue = new { ok = true, banId };
            break;
        }
        case "clear":
            ts.Send("bandelall");
            Globals.ReturnValue = new { ok = true };
            break;
        default:
            throw Fail($"Unknown TsAction '{action}'. Use list, add, delete or clear.");
    }
}


