/// <summary>Channels of the selected virtual server as browser rows, in TeamSpeak's display order.</summary>
List<Dictionary<string, object>> ChannelRows(Ts3Query ts)
{
    var rows = ts.Send("channellist -topic -flags -voice -limits").Where(c => c.ContainsKey("cid")).ToList();
    var byParent = rows.GroupBy(c => Ni(c, "pid")).ToDictionary(g => g.Key, g => g.ToList());
    var ordered = new List<Dictionary<string, object>>();
    void Walk(int pid, int depth)
    {
        if (!byParent.TryGetValue(pid, out var children)) return;
        // channel_order is the id of the channel ABOVE a channel; 0 = first.
        var remaining = children.ToList();
        int previous = 0;
        while (remaining.Count > 0)
        {
            var next = remaining.FirstOrDefault(c => Ni(c, "channel_order") == previous) ?? remaining[0];
            remaining.Remove(next);
            int cid = Ni(next, "cid");
            ordered.Add(new Dictionary<string, object>
            {
                ["cid"] = cid, ["pid"] = pid, ["depth"] = depth,
                ["name"] = Nz(next, "channel_name"), ["topic"] = Nz(next, "channel_topic"),
                ["clients"] = Ni(next, "total_clients"),
                ["maxClients"] = Ni(next, "channel_flag_maxclients_unlimited") == 1 ? -1 : Ni(next, "channel_maxclients", -1),
                ["permanent"] = Ni(next, "channel_flag_permanent") == 1,
                ["semiPermanent"] = Ni(next, "channel_flag_semi_permanent") == 1,
                ["isDefault"] = Ni(next, "channel_flag_default") == 1,
                ["passworded"] = Ni(next, "channel_flag_password") == 1,
                ["codec"] = Ni(next, "channel_codec"), ["codecQuality"] = Ni(next, "channel_codec_quality"),
                ["neededTalkPower"] = Ni(next, "channel_needed_talk_power"),
                ["neededSubscribePower"] = Ni(next, "channel_needed_subscribe_power")
            });
            previous = cid;
            Walk(cid, depth + 1);
        }
    }
    Walk(0, 0);
    return ordered;
}

