// API function "TsPrivilegeKeys": the privilege keys (tokens) of a virtual server, for the TeamSpeak Browser page.
// TsAction = list | create | delete.
// list    -> { keys: [{ token, type, groupId, group, channelId, created, description }], groups: [{ sgid, name }] }
// create  TsGroupId (0 = the Server Admin group), TsDescription -> { token, group }
// delete  TsToken
var action = Action();
using (var ts = Ts3Connect())
{
    int sid = UseSid(ts);
    var groups = ServerGroups(ts);
    switch (action)
    {
        case "list":
            Globals.ReturnValue = new Dictionary<string, object>
            {
                ["keys"] = ts.Send("privilegekeylist").Where(k => k.ContainsKey("token")).Select(k => new Dictionary<string, object>
                {
                    ["token"] = Nz(k, "token"), ["type"] = Ni(k, "token_type"), ["groupId"] = Ni(k, "token_id1"),
                    ["group"] = Ni(k, "token_type") == 0 && groups.TryGetValue(Ni(k, "token_id1"), out var g) ? g : "",
                    ["channelId"] = Ni(k, "token_id2"), ["created"] = Nl(k, "token_created"), ["description"] = Nz(k, "token_description")
                }).ToList(),
                ["groups"] = groups.OrderBy(g => g.Key).Select(g => new Dictionary<string, object> { ["sgid"] = g.Key, ["name"] = g.Value }).ToList()
            };
            break;
        case "create":
        {
            int sgid = IntArg("TsGroupId");
            if (sgid <= 0)
            {
                // The Server Admin group: by its template name, else the regular group with the lowest id.
                sgid = groups.FirstOrDefault(g => g.Value.Equals("Server Admin", StringComparison.OrdinalIgnoreCase)).Key;
                if (sgid == 0 && groups.Count > 0) sgid = groups.Keys.Min();
                if (sgid == 0) throw Fail("This virtual server has no server groups to create a key for.");
            }
            var key = ts.SendSingle($"privilegekeyadd tokentype=0 tokenid1={sgid} tokenid2=0 tokendescription={Ts3Query.Escape(Arg("TsDescription", "Created in the TCAdmin TeamSpeak Browser"))}");
            Globals.ReturnValue = new { token = Nz(key, "token"), groupId = sgid, group = groups.TryGetValue(sgid, out var name) ? name : $"#{sgid}" };
            break;
        }
        case "delete":
        {
            var token = Arg("TsToken").Trim(); if (token.Length == 0) throw Fail("TsToken is required.");
            ts.Send($"privilegekeydelete token={Ts3Query.Escape(token)}");
            Globals.ReturnValue = new { ok = true };
            break;
        }
        default:
            throw Fail($"Unknown TsAction '{action}'. Use list, create or delete.");
    }
}


